CREATE TYPE "AccountStatus" AS ENUM ('ACTIVE','WARNED','SUSPENDED','BANNED');
CREATE TYPE "PaymentStatus" AS ENUM ('PENDING','PAID','FAILED','REFUND_PENDING','REFUNDED');
CREATE TYPE "PaymentMethod" AS ENUM ('PAYSTACK','CASH');
CREATE TYPE "SupportStatus" AS ENUM ('OPEN','IN_PROGRESS','RESOLVED','CLOSED');
CREATE TYPE "DisputeStatus" AS ENUM ('OPEN','UNDER_REVIEW','RESOLVED','REFUNDED','REJECTED');
CREATE TYPE "CaseStatus" AS ENUM ('OPEN','UNDER_REVIEW','ACTIONED','DISMISSED');
CREATE TYPE "ModerationActionType" AS ENUM ('WARNING','SUSPEND','BAN','REINSTATE');
CREATE TYPE "AppealStatus" AS ENUM ('OPEN','APPROVED','REJECTED');
ALTER TABLE "User" ADD COLUMN "status" "AccountStatus" NOT NULL DEFAULT 'ACTIVE';
ALTER TABLE "ServiceRequest" ADD COLUMN "appointmentAt" TIMESTAMP(3), ADD COLUMN "agreedPrice" DOUBLE PRECISION, ADD COLUMN "priceApproved" BOOLEAN NOT NULL DEFAULT false;
CREATE TABLE "Message" ("id" TEXT NOT NULL,"requestId" TEXT NOT NULL,"senderId" TEXT NOT NULL,"body" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"readAt" TIMESTAMP(3),CONSTRAINT "Message_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Payment" ("id" TEXT NOT NULL,"requestId" TEXT NOT NULL,"payerId" TEXT NOT NULL,"providerId" TEXT NOT NULL,"reference" TEXT NOT NULL,"amountKobo" INTEGER NOT NULL,"commissionKobo" INTEGER NOT NULL DEFAULT 0,"providerAmountKobo" INTEGER NOT NULL,"method" "PaymentMethod" NOT NULL,"status" "PaymentStatus" NOT NULL DEFAULT 'PENDING',"authorizationUrl" TEXT,"paidAt" TIMESTAMP(3),"cashReportedAt" TIMESTAMP(3),"cashConfirmedAt" TIMESTAMP(3),"cashConfirmedByPartner" BOOLEAN NOT NULL DEFAULT false,"cashConfirmedByProvider" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Payment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Dispute" ("id" TEXT NOT NULL,"requestId" TEXT NOT NULL,"openedById" TEXT NOT NULL,"reason" TEXT NOT NULL,"evidenceText" TEXT,"status" "DisputeStatus" NOT NULL DEFAULT 'OPEN',"resolution" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Dispute_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SupportTicket" ("id" TEXT NOT NULL,"creatorId" TEXT NOT NULL,"requestId" TEXT,"subject" TEXT NOT NULL,"category" TEXT NOT NULL,"description" TEXT NOT NULL,"status" "SupportStatus" NOT NULL DEFAULT 'OPEN',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SupportTicket_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SupportMessage" ("id" TEXT NOT NULL,"ticketId" TEXT NOT NULL,"senderId" TEXT NOT NULL,"body" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SupportMessage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ModerationCase" ("id" TEXT NOT NULL,"reporterId" TEXT NOT NULL,"targetUserId" TEXT NOT NULL,"requestId" TEXT,"category" TEXT NOT NULL,"description" TEXT NOT NULL,"aiSummary" TEXT,"aiRiskLevel" TEXT,"status" "CaseStatus" NOT NULL DEFAULT 'OPEN',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ModerationCase_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ModerationAction" ("id" TEXT NOT NULL,"caseId" TEXT,"targetUserId" TEXT NOT NULL,"adminId" TEXT NOT NULL,"type" "ModerationActionType" NOT NULL,"reason" TEXT NOT NULL,"expiresAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ModerationAction_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Appeal" ("id" TEXT NOT NULL,"actionId" TEXT NOT NULL,"userId" TEXT NOT NULL,"reason" TEXT NOT NULL,"status" "AppealStatus" NOT NULL DEFAULT 'OPEN',"resolution" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"reviewedAt" TIMESTAMP(3),CONSTRAINT "Appeal_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PolicyAcceptance" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"policyVersion" TEXT NOT NULL,"termsAcceptedAt" TIMESTAMP(3) NOT NULL,"privacyAcceptedAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PolicyAcceptance_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Payment_reference_key" ON "Payment"("reference");
CREATE INDEX "Message_requestId_createdAt_idx" ON "Message"("requestId","createdAt");
CREATE INDEX "Payment_requestId_createdAt_idx" ON "Payment"("requestId","createdAt");
CREATE INDEX "Payment_providerId_status_method_idx" ON "Payment"("providerId","status","method");
CREATE INDEX "Dispute_status_createdAt_idx" ON "Dispute"("status","createdAt");
CREATE INDEX "SupportTicket_creatorId_status_createdAt_idx" ON "SupportTicket"("creatorId","status","createdAt");
CREATE INDEX "SupportTicket_status_createdAt_idx" ON "SupportTicket"("status","createdAt");
CREATE INDEX "SupportMessage_ticketId_createdAt_idx" ON "SupportMessage"("ticketId","createdAt");
CREATE INDEX "ModerationCase_status_createdAt_idx" ON "ModerationCase"("status","createdAt");
CREATE INDEX "ModerationCase_targetUserId_createdAt_idx" ON "ModerationCase"("targetUserId","createdAt");
CREATE INDEX "ModerationAction_targetUserId_createdAt_idx" ON "ModerationAction"("targetUserId","createdAt");
CREATE INDEX "Appeal_status_createdAt_idx" ON "Appeal"("status","createdAt");
CREATE UNIQUE INDEX "PolicyAcceptance_userId_policyVersion_key" ON "PolicyAcceptance"("userId","policyVersion");
CREATE INDEX "ServiceRequest_appointmentAt_status_idx" ON "ServiceRequest"("appointmentAt","status");
ALTER TABLE "Message" ADD CONSTRAINT "Message_requestId_fkey" FOREIGN KEY ("requestId") REFERENCES "ServiceRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT "Message_senderId_fkey" FOREIGN KEY ("senderId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Payment" ADD CONSTRAINT "Payment_requestId_fkey" FOREIGN KEY ("requestId") REFERENCES "ServiceRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT "Payment_payerId_fkey" FOREIGN KEY ("payerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT "Payment_providerId_fkey" FOREIGN KEY ("providerId") REFERENCES "ProviderProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Dispute" ADD CONSTRAINT "Dispute_requestId_fkey" FOREIGN KEY ("requestId") REFERENCES "ServiceRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT "Dispute_openedById_fkey" FOREIGN KEY ("openedById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SupportTicket" ADD CONSTRAINT "SupportTicket_creatorId_fkey" FOREIGN KEY ("creatorId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT "SupportTicket_requestId_fkey" FOREIGN KEY ("requestId") REFERENCES "ServiceRequest"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "SupportMessage" ADD CONSTRAINT "SupportMessage_ticketId_fkey" FOREIGN KEY ("ticketId") REFERENCES "SupportTicket"("id") ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT "SupportMessage_senderId_fkey" FOREIGN KEY ("senderId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ModerationCase" ADD CONSTRAINT "ModerationCase_reporterId_fkey" FOREIGN KEY ("reporterId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT "ModerationCase_targetUserId_fkey" FOREIGN KEY ("targetUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT "ModerationCase_requestId_fkey" FOREIGN KEY ("requestId") REFERENCES "ServiceRequest"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "ModerationAction" ADD CONSTRAINT "ModerationAction_caseId_fkey" FOREIGN KEY ("caseId") REFERENCES "ModerationCase"("id") ON DELETE SET NULL ON UPDATE CASCADE, ADD CONSTRAINT "ModerationAction_targetUserId_fkey" FOREIGN KEY ("targetUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT "ModerationAction_adminId_fkey" FOREIGN KEY ("adminId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Appeal" ADD CONSTRAINT "Appeal_actionId_fkey" FOREIGN KEY ("actionId") REFERENCES "ModerationAction"("id") ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT "Appeal_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "PolicyAcceptance" ADD CONSTRAINT "PolicyAcceptance_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
